package com.toabea.closet.config;
import com.toabea.closet.common.ApiModels; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiModels.ErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){return body(HttpStatus.BAD_REQUEST,"Validation failed",r);} @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<ApiModels.ErrorResponse> client(RuntimeException e,HttpServletRequest r){return body(HttpStatus.CONFLICT,e.getMessage(),r);} private ResponseEntity<ApiModels.ErrorResponse> body(HttpStatus s,String m,HttpServletRequest r){return ResponseEntity.status(s).body(new ApiModels.ErrorResponse(Instant.now(),s.value(),s.getReasonPhrase(),m,r.getRequestURI()));} }
